"use client";

import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { getSongs } from "@/lib/api";
import SongCard from "@/components/SongCard";
import { Song } from "@/types/song";

export default function MusicLibraryPage() {
  const searchParams = useSearchParams();

  // URL params (single source of truth)
  const listenedParam = searchParams.get("listened"); // "true" | "false" | null
  const recommendedBy = searchParams.get("friends_recommended");
  const tag = searchParams.get("my_tags");

  const sortBy = searchParams.get("sort_by") ?? "created_at";
  const order = searchParams.get("order") ?? "desc";

  const [songs, setSongs] = useState<Song[]>([]);
  const [message, setMessage] = useState<string | null>(null);

  // 🔄 Fetch songs from backend using filters
  const loadSongs = async () => {
    const params: any = {
      sort_by: sortBy,
      order,
      limit: 100,
    };

    if (listenedParam === "true") params.listened = true;
    if (listenedParam === "false") params.listened = false;

    if (recommendedBy) params.friends_recommended = recommendedBy;

    if (tag) params.my_tags = tag;

    const data = await getSongs(params);
    setSongs(data);
  };

  useEffect(() => {
    loadSongs();
  }, [listenedParam, recommendedBy, tag, sortBy, order]);

  return (
    <main style={{ padding: 32 }}>
      <h1>🎵 Music</h1>

      {/* FILTER BAR */}
      <div style={{ display: "flex", gap: 12, marginBottom: 16 }}>
        {/* Listened filter */}
        <select
          value={listenedParam ?? ""}
          onChange={(e) => {
            const params = new URLSearchParams(window.location.search);

            if (e.target.value) params.set("listened", e.target.value);
            else params.delete("listened");

            window.location.href = `/library/music?${params.toString()}`;
          }}
        >
          <option value="">All</option>
          <option value="true">Listened</option>
          <option value="false">Unlistened</option>
        </select>

        {/* Sort field */}
        <select
          value={sortBy}
          onChange={(e) => {
            const params = new URLSearchParams(window.location.search);
            params.set("sort_by", e.target.value);
            if (!params.get("order")) {
              params.set("order", "desc");
            }

            window.location.href = `/library/music?${params.toString()}`;
          }}
        >
          <option value="created_at">Recently added</option>
          <option value="rating">Rating</option>
          <option value="year">Year</option>
          <option value="title">Title</option>
          <option value="artist">Artist</option>
        </select>

        {/* Sort order */}
        <select
          value={order}
          onChange={(e) => {
            const params = new URLSearchParams(window.location.search);
            params.set("order", e.target.value);

            window.location.href = `/library/music?${params.toString()}`;
          }}
        >
          <option value="desc">↓ Descending</option>
          <option value="asc">↑ Ascending</option>
        </select>
      </div>

      {/* ACTIVE FILTER CHIPS */}
      <div
        style={{
          display: "flex",
          gap: 8,
          flexWrap: "wrap",
          marginBottom: 24,
        }}
      >
        {listenedParam && (
          <FilterChip
            label={listenedParam === "true" ? "Listened" : "Unlistened"}
            onRemove={() => removeParam("listened")}
          />
        )}

        {recommendedBy && (
          <FilterChip
            label={`Recommended by ${recommendedBy}`}
            onRemove={() => removeParam("friends_recommended")}
          />
        )}

        {tag && (
          <FilterChip
            label={`#${tag}`}
            onRemove={() => removeParam("my_tags")}
          />
        )}

        {(sortBy !== "created_at" || order !== "desc") && (
          <FilterChip
            label={`Sorted by ${sortBy} (${order})`}
            onRemove={() => {
              removeParam("sort_by");
              removeParam("order");
            }}
          />
        )}
      </div>

      {/* SONG LIST */}
      {songs.map((song) => (
        <SongCard
          key={song.song_id}
          song={song}
          onListened={(msg) => {
            setMessage(msg);
            setTimeout(() => setMessage(null), 3000);
            loadSongs();
          }}
        />
      ))}

      {message && <Toast message={message} />}
    </main>
  );
}

/* ---------- Helpers ---------- */

function removeParam(key: string) {
  const params = new URLSearchParams(window.location.search);
  params.delete(key);

  window.location.href = `/library/music?${params.toString()}`;
}

function FilterChip({
  label,
  onRemove,
}: {
  label: string;
  onRemove: () => void;
}) {
  return (
    <span
      style={{
        display: "flex",
        alignItems: "center",
        gap: 6,
        padding: "4px 10px",
        borderRadius: 16,
        background: "#222",
        fontSize: 12,
      }}
    >
      {label}
      <button
        onClick={onRemove}
        style={{
          background: "none",
          border: "none",
          color: "#aaa",
          cursor: "pointer",
        }}
      >
        ✕
      </button>
    </span>
  );
}

function Toast({ message }: { message: string }) {
  return (
    <div
      style={{
        position: "fixed",
        bottom: 24,
        right: 24,
        background: "#1b5e20",
        color: "#c8e6c9",
        padding: "12px 16px",
        borderRadius: 10,
      }}
    >
      {message}
    </div>
  );
}
